insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 1, 'How is net pressure defined for a hydraulic fracture?', '["It is the fluid pressure inside the fracture at the wellbore.", "It is the difference between the surface treating pressure and the hydrostatic head of the slurry in the tubing.", "It is the fluid pressure inside the fracture less the closure stress that the rock imposes on the faces.", "It is the difference between the fracturing pressure and the reservoir pressure across the interval being treated."]'::jsonb, 2, 'The first part of the fluid pressure is spent balancing the earth, and only the surplus is available to do work.'),
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 2, 'In the published case, how does the PKN net pressure of 2.889736 MPa compare with the closure stress?', '["It is under a tenth of the closure stress of 38.13195 MPa, so the surplus is a small part of the total.", "It is a little larger than closure, by design.", "It is roughly half of the closure stress, which is the usual proportion for a treatment in a competent sandstone.", "It is equal to closure, since the fracture is held exactly on the point of opening throughout the treatment."]'::jsonb, 0, 'The number that creates the fracture is far smaller than the number a gauge would read in the wellbore.'),
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 3, 'What does the surplus above closure buy during a treatment?', '["It keeps the proppant suspended in the slurry.", "It raises the reservoir pressure near the fracture so that leakoff into the formation is suppressed while pumping.", "It reduces the friction in the tubing, because a higher pressure at the perforations slows the fluid entering them.", "It holds the fracture open against the rock and pays for growth in both length and height at the same time."]'::jsonb, 3, 'This is why a real time net pressure record is read as a record of what the fracture is doing underground.'),
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 4, 'Under what conditions does `planeStrainModulus` refuse to return a value?', '["When the closure stress has not been supplied to the engine.", "When Young''s modulus is not positive, or when the Poisson ratio lies outside the open interval from 0 to 0.5.", "When the fracture half length has not yet been chosen, since the modulus is evaluated after the geometry is fixed.", "When the Poisson ratio exceeds 0.28, the published value, because the width coefficients were derived at that ratio."]'::jsonb, 1, 'Both refusals are physical, since a ratio of 0.5 is incompressible and anything above it is elastically inadmissible.'),
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 5, 'How does the engine arrive at the bottomhole treating pressure of 41.021687 MPa?', '["It adds the PKN net pressure straight back onto the closure stress that the rock imposes at that depth.", "It multiplies closure by a model dependent factor.", "It adds the slurry hydrostatic column to the surface treating pressure recorded at the start of the step rate test.", "It subtracts the reservoir pressure from closure and then applies the width coefficient appropriate to the model."]'::jsonb, 0, 'Slurry hydrostatic and pipe and perforation friction are out of scope, so this is a bottomhole and not a surface number.'),
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 6, 'The KGD entry in the published table shows a treating pressure of 38.734295 MPa. Why does it differ from the PKN entry?', '["The two models assume different closure stresses.", "The KGD model is evaluated at a shallower depth, which lowers the overburden and therefore the treating pressure.", "Only the net pressure depends on the fracture model, and the KGD net pressure is the smaller of the two.", "The two entries were computed at different injection rates, and treating pressure scales directly with the rate."]'::jsonb, 2, 'Both rows share the closure stress of 38.13195 MPa, which the rock sets and no model is free to change.'),
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 7, 'Which contributions does the engine put explicitly out of scope when it reports treating pressure?', '["The closure stress and the reservoir pressure.", "Slurry hydrostatic head along with pipe friction and perforation friction, all of which sit above the perforations.", "The net pressure, since it is model dependent and therefore cannot be quoted alongside a measured field pressure.", "The elastic properties of the rock, because they enter the width calculation rather than the pressure calculation."]'::jsonb, 1, 'Scoping the answer at the perforations keeps the comparison honest, since a surface number needs the whole tubing string.'),
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 8, 'What does the engine return when no closure stress is supplied at all?', '["It assumes a closure gradient and completes the calculation.", "It refuses the whole calculation, since a fracture model cannot produce a width without a stress to open against.", "It substitutes the reservoir pressure for closure, on the argument that the two converge in a depleted formation.", "It reports the net pressure and leaves the treating pressure empty rather than guessing at a closure value."]'::jsonb, 3, 'An empty field is a visible gap, whereas a quietly assumed gradient would look like a computed result.'),
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 9, 'Which stress does a hydraulic fracture open against, and how does the plane orient itself?', '["Against the overburden, with a horizontal fracture plane.", "Against the maximum horizontal stress, with the plane running parallel to it because that is the stiffest direction.", "Against the average of the three principal stresses, with the plane set by the perforation phasing at the wellbore.", "Against the minimum principal stress, with the plane taking up the orientation perpendicular to that stress."]'::jsonb, 3, 'At normal depths the minimum principal stress is horizontal, so closure is the minimum horizontal stress at that depth.'),
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 10, 'Why is closure read from a stress profile rather than taken from a gradient off a chart?', '["Because charts are quoted in imperial units and need conversion.", "The minimum horizontal stress varies bed to bed with stiffness, pore pressure and tectonic history.", "Because the gradient method gives the vertical stress rather than the horizontal one, and the two are never related.", "Because a chart gradient applies only to carbonates, whereas the fracture models in this tier assume a clastic section."]'::jsonb, 1, 'Those bed to bed contrasts are what contain the height, so the profile rather than any single value is the deliverable.'),
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 11, 'The published interval runs from 2450 m to 2550 m measured depth. Why is the stress looked up at 2124.897478 m instead of the mid point of that range?', '["Stress follows true vertical depth, and the well is deviated, so the mid point measured depth sits far too deep.", "Because the perforations are shot above the mid point.", "Because the engine works in true vertical depth only for closure and in measured depth for every other quantity.", "Because the interval is corrected for the thickness of the shale barriers found above and below the target sand."]'::jsonb, 0, 'Using 2500 m would place the perforations more than three hundred metres deeper than they are, with a matching error in stress.'),
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 12, 'An engineer''s closure stress estimate is too high by some fixed amount. What happens to the predicted treating pressure?', '["It is unaffected, since net pressure absorbs the error.", "It is too high by rather less, because the fracture model reduces the net pressure to compensate for the stiffer rock.", "It is too high by exactly that amount, because closure enters the sum one for one with no damping at all.", "It is too high by more, since the width calculation feeds the error back into the net pressure a second time."]'::jsonb, 2, 'Closure is the large fixed part of the treating pressure, so accuracy there matters more than accuracy in the model.'),
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 13, 'How is the plane strain modulus obtained from the published elastic pair?', '["Young''s modulus is multiplied by the Poisson ratio of 0.28.", "Young''s modulus of 25 GPa is divided by one minus the square of 0.28, which gives 27.126736 GPa.", "Young''s modulus is divided by one minus the Poisson ratio, with no squaring, which overstates the stiffening badly.", "Young''s modulus is averaged with the shear modulus, and the Poisson ratio decides the weighting between them."]'::jsonb, 1, 'The engine evaluates it before any geometry is touched, and both fracture models then take the plane strain value.'),
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 14, 'Why is the few per cent correction from E to E prime still worth making?', '["Because it makes the predicted width considerably narrower.", "Because the correction grows without limit as the Poisson ratio rises, so it can dominate at high ratios in shale.", "Because the fourth root in the width equation amplifies the correction, turning a few per cent into a large change.", "The published width coefficients 2.31 and 3.22 were derived with the plane strain value in the denominator."]'::jsonb, 3, 'Even at the incompressible limit the denominator is only 0.75, so the plane strain value cannot exceed four thirds of E.'),
  ('stimulation', 'intermediate', 'module', 'm01-a-fracture-is-a-pressure-problem', 15, 'Why does confinement give E over one minus nu squared rather than E on its own?', '["The rock at the fracture face cannot bulge sideways into ground already occupied, so it gives way less readily.", "Because the rock is stronger under compression than in tension.", "Because the fluid pressure inside the fracture stiffens the rock chemically over the duration of the treatment.", "Because the fracture faces are rough, and the asperities carry part of the load in the way a proppant pack would."]'::jsonb, 0, 'PKN takes the strain as zero in vertical cross sections while KGD takes it as zero in horizontal planes, with the same factor.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 1, 'Cut a vertical slice through a PKN fracture. What does the opening look like across that slice?', '["A rectangle of constant width from top to bottom.", "A wedge that is widest at the upper barrier and narrows steadily downwards towards the base of the pay interval.", "An ellipse that is widest at mid height and tapers to nothing at the top and bottom boundaries.", "A circle whose diameter equals the assumed fracture height."]'::jsonb, 2, 'Slices taken further from the well show the same elliptical shape but shrinking towards the tip.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 2, 'In KGD the vertical section is treated as effectively constant. Which shape does that give a slice cut across the height?', '["A rectangle, because the whole height opens together at the same width and the height is not what holds it shut.", "An ellipse tapering to zero at each barrier.", "A parabola whose vertex sits at the wellbore.", "A shape that varies with depth because each horizontal layer of rock carries a different share of the internal pressure."]'::jsonb, 0, 'The elliptical taper in KGD lives in plan view instead, running from the well out to the tip.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 3, 'KGD is defined by an assumption about which plane carries the plane strain deformation. Which plane is it?', '["The vertical plane along the fracture length.", "The plane normal to the minimum horizontal stress.", "A plane inclined between horizontal and vertical, chosen so that both the height and the length contribute to the compliance.", "The horizontal plane, so every horizontal slice solves the same Griffith through crack problem."]'::jsonb, 3, 'Height in KGD is only a multiplier counting how many identical horizontal slices are stacked.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 4, 'Where does fracture height appear in the PKN equations the engine uses?', '["In the width bracket and in the net pressure together.", "Only in the net pressure expression, in the denominator, and nowhere at all inside the width bracket.", "In the width bracket alone.", "In neither expression, since PKN treats the height as a purely cosmetic reporting quantity added after the fact."]'::jsonb, 1, 'That is why a PKN width is indifferent to the height you assume while its net pressure is fully exposed to it.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 5, 'Compare the KGD width bracket with the PKN one. How do half-length and height enter the KGD version?', '["Half-length appears squared and height appears in the denominator, both under the same quarter power.", "Both appear to the first power in the numerator.", "Half-length appears to the first power and height does not appear at all, exactly as in the PKN bracket.", "Height appears squared and half-length appears to the first power."]'::jsonb, 0, 'Height divides because a fixed injection rate is shared out over a larger number of identical horizontal slices.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 6, 'Why does PKN average with a shape factor of pi over five while KGD uses pi over four?', '["PKN uses a coarser approximation to the ellipse.", "The two factors come from different definitions of average width rather than from any difference in the fracture shape itself.", "PKN tapers twice, elliptically across the height and again towards the tip, whereas KGD tapers only in plan view.", "KGD includes the wellbore radius in its averaging."]'::jsonb, 2, 'That single difference in shape factor puts a further five to four on the width comparison between the models.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 7, 'State the rule of thumb that decides which of the two models to use on a given design.', '["Use KGD for all cased and perforated completions.", "Compare length against height and pick the model whose controlling dimension is genuinely the smaller one.", "Use PKN when the fracture is long relative to its height and KGD when it is short relative to its height.", "Choose whichever model gives the more conservative treating pressure once both have been run at the design conditions."]'::jsonb, 1, 'The smaller dimension controls because it is the shorter path over which the rock has to be pushed aside.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 8, 'The published design targets a half-length of 150 m in a fracture height of 30 m. Which model does the rule of thumb select, and how clearly?', '["KGD, because the height is small in absolute terms.", "Neither, since the two dimensions are within a factor of two of one another.", "PKN at the design point but KGD over the lower half of the sweep, so the model has to be switched partway through the calculation.", "PKN, and without ambiguity, because length beats height fivefold across the whole sweep from 40 m to 300 m."]'::jsonb, 3, 'Most real designs aim for a contained fracture far longer than it is tall, so this clarity is common in practice.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 9, 'Why does the length against height comparison remain a rule of thumb rather than a proper criterion?', '["Nothing tells you where the switch happens, and neither model announces its own failure near the crossover.", "Because the published case sits too far from the crossover.", "Because the comparison uses a height that is itself an assumption, which is the only weakness the rule has.", "Because the two models were published in different decades and their coefficients were never reconciled against a common set of laboratory experiments."]'::jsonb, 0, 'A single model for the whole job is a decision to be wrong at one end, since every treatment starts short and tall and ends long and contained.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 10, 'What does the fracGeometry routine refuse, and what does it let through?', '["It rejects a KGD run whenever half-length exceeds height.", "It rejects non-positive inputs and unknown model names but accepts any pairing of model with geometry.", "It refuses non-positive rate, viscosity, half-length, height or modulus, and refuses a model name it does not recognise, yet it will not refuse a badly matched model and geometry.", "It silently substitutes PKN whenever the geometry looks contained."]'::jsonb, 1, 'The engine cannot police the pairing because it has no way of knowing which of the two dimensions you actually trust.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 11, 'At the published half-length of 150 m, how does the KGD average width compare with the PKN average width?', '["The two agree to within a few per cent.", "PKN gives roughly twice the KGD width.", "KGD gives 2.605532 times the PKN average width, on the same rock, rate, fluid and target length.", "KGD is wider by a fixed offset of about six millimetres that holds at every half-length in the published sweep."]'::jsonb, 2, 'Nothing physical changes between the two columns, only the assumption about which direction the rock is confined in.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 12, 'Read the width ratio down the sweep from 40 m to 300 m. What happens to the disagreement, and why?', '["It stays constant, since both models share the same quarter power.", "It narrows, because the two solutions converge in long fractures.", "It widens at first and then narrows again once the half-length passes roughly twice the assumed fracture height.", "It widens from 1.872357 to 3.098517, because PKN width goes as length to the quarter and KGD as length to the half."]'::jsonb, 3, 'So the models agree best in the geometry neither of them is comfortable in and disagree most in the long fracture designs actually aim for.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 13, 'Across the six half-lengths in the sweep, what do the two net pressure trends do?', '["Both rise, though at different rates.", "PKN net pressure rises from 2.076588 MPa to 3.436495 MPa while KGD falls from 1.166434 MPa to 0.425921 MPa.", "PKN rises while KGD falls, so one input set produces opposite signs on the slope from the two models.", "Both fall, because a longer fracture is always easier to keep open once it has grown past its own height."]'::jsonb, 1, 'That opposition is exactly what makes net pressure matching a usable field diagnostic.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 14, 'Trace the compliance terms. Why do the two net pressure slopes carry opposite signs?', '["PKN divides by a fixed height while KGD divides by a growing length that outruns its own width.", "Because PKN and KGD use different closure stresses.", "Because the PKN coefficient of 2.31 is smaller than the KGD coefficient of 3.22, which reverses the sense of the trend.", "Because the PKN numerator climbs with the quarter power of half-length against a constant denominator, while the KGD denominator of four times half-length grows faster than its square root width."]'::jsonb, 0, 'A longer PKN fracture is harder to keep open and a longer KGD fracture is easier, each consistent inside its own model.'),
  ('stimulation', 'intermediate', 'module', 'm02-two-two-dimensional-models', 15, 'A designer picks KGD on a well that is really behaving as PKN. What is lost beyond the error in magnitude?', '["Only the treating pressure estimate, which is out by a small margin.", "The average width prediction alone, which is recoverable once the job has been pumped and the pressure record is available for a match.", "The trend is inverted, so a rising field record gets misread as a screenout or as height growth.", "Nothing that matters, since both models bracket the truth."]'::jsonb, 2, 'A magnitude error can be calibrated out, but a direction error cannot, because the diagnostic you would calibrate against is the trend itself.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 1, 'A fracture has two widths. Which of them does the material balance actually spend?', '["The maximum width, taken at the wellbore.", "The average width over the whole face, since the fracture volume is two wings of length, height and average width.", "The average of the two, weighted by the shape factor.", "Whichever of them the chosen model happens to report first, because the balance is written to accept either one as its input."]'::jsonb, 1, 'On the published PKN case that volume comes to 36.143836842230584 m3 of fracture.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 2, 'What does the maximum width decide that the average width does not?', '["How much fluid the fracture holds.", "The pad fraction and the fluid efficiency.", "The leaking area of the fracture faces, which sets how much of the injected volume is lost to the formation during the treatment.", "Whether a slurry will bridge near the well, since it is the opening the proppant has to pass through."]'::jsonb, 3, 'It is the width at the wellbore at the centre of the fracture face, the widest the crack ever gets.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 3, 'Explain how the PKN shape factor of pi over five is built up from the geometry.', '["An ellipse averages pi over four of its maximum, and the taper along the length contributes a further four fifths.", "It is an empirical fit to laboratory fracture moulds.", "It comes from dividing the elliptical factor by the ratio of length to height at the design point.", "It is the ratio of the two model coefficients, 2.31 against 3.22, rounded to a convenient closed form for hand calculation."]'::jsonb, 0, 'PKN is the leaner shape, so for the same maximum width it holds less fluid than KGD does.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 4, 'Why does KGD keep the plain elliptical factor of pi over four?', '["Because it ignores the taper towards the tip.", "Because its coefficient of 3.22 already absorbs the second taper.", "Its width profile is elliptical in plan view only, with the vertical section treated as constant over the height.", "Because KGD averages across the height alone and leaves the variation along the length out of the calculation entirely."]'::jsonb, 2, 'One ellipse instead of two separate effects is the whole difference between the two shape factors.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 5, 'Expressed as decimals, what fraction of the maximum width does each model report as the average?', '["Both give 0.7853981633974483 of the maximum.", "PKN gives 0.7853981633974483 and KGD gives 0.6283185307179585.", "PKN gives 0.8 of the maximum and KGD gives 1.0, since the KGD section does not taper at all in the vertical direction.", "PKN gives 0.6283185307179585 of the maximum and KGD gives 0.7853981633974483 of it."]'::jsonb, 3, 'The two constants are simply pi over five and pi over four written out.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 6, 'The width models raise a bracket of treatment and rock terms to a single exponent. What is that exponent, and what does it do?', '["One half, so four times the input doubles the width.", "One quarter, which flattens everything, so sixteen times the input buys exactly twice the output.", "The power 0.25, which means a sixteenfold increase in the bracket yields a doubling of the width.", "Unity, so width tracks the bracket in direct proportion once the model coefficient has been applied."]'::jsonb, 1, 'Both models share the same structure, so the flattening applies to PKN and KGD alike.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 7, 'How do rate, viscosity and half-length sit inside the PKN bracket relative to one another?', '["All three enter to the first power, so the quarter power treats them as interchangeable and equally weak levers.", "Rate enters squared and the other two to the first power.", "Viscosity dominates because crosslinked fluids raise it by orders of magnitude.", "Half-length enters to the first power while rate and viscosity are combined into a single product that is then squared inside the bracket."]'::jsonb, 0, 'The published sweep varies half-length, but rate sits in the same bracket at the same power, so the same rule governs it.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 8, 'Over the sweep the half-length rises by a factor of 7.5. What happens to the two average widths?', '["Both rise by 1.6548754598234365.", "Both rise by the full factor of 7.5, since width is proportional to length in each model.", "PKN width rises by 1.6548754598234365 and KGD by 2.7386127875258306, which are 7.5 raised to a quarter and to a half.", "PKN rises by 2.7386127875258306 and KGD by 1.6548754598234365, because the KGD bracket carries the height in its denominator."]'::jsonb, 2, 'KGD moves faster because half-length enters its bracket squared, so the quarter power halves the exponent rather than quartering it.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 9, 'What does the quarter power mean for a designer trying to pump extra width into a fracture?', '["A modest rate increase buys a proportional width increase.", "Width is not something you can pump your way into, since no realistic rate increase comes close to doubling it.", "Width cannot be bought with rate, and viscosity behaves the same way, which is why crosslinked fluids never widen a fracture by the factor their viscosity ratio suggests.", "Only viscosity is damped, so rate remains the practical lever for widening a fracture on location."]'::jsonb, 1, 'The damping runs both ways, so a viscosity estimate wrong by a factor of eight leaves the width wrong by less than a factor of two.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 10, 'Each model reaches net pressure from the same numerator but a different length scale. Which scale does each use?', '["PKN divides by twice the height and KGD divides by four times the half-length, following each elasticity solution.", "PKN divides by half-length and KGD by height.", "Both divide by the height, differing only in the leading constant.", "PKN divides by twice the height while KGD divides by the product of height and half-length, which is why its net pressure is so much lower."]'::jsonb, 0, 'PKN is confined vertically, so the resisting rock spans the height, while KGD is a through crack in plan view.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 11, 'Trace the denominators through a job. Why does one net pressure climb while the other drops?', '["Because the two models assume different closure stresses.", "Because KGD loses more fluid to leakoff as the fracture extends.", "Because the PKN numerator grows with the quarter power of half-length against a fixed height, while the KGD width grows only with the square root of a half-length that also divides it.", "The PKN denominator is frozen because height is an input, whereas the growing KGD denominator outruns its own width."]'::jsonb, 3, 'That divergence widens from a factor of 1.7802875565431469 at 40 m to 8.06837553533979 at 300 m.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 12, 'A treatment record shows net pressure climbing steadily through the job. What reading does the module give it?', '["It indicates a screenout in progress.", "It shows the fluid viscosity degrading downhole.", "The well is behaving like PKN, which is consistent with a height held between competent barriers.", "It points to KGD behaviour, since a longer fracture with a growing compliance denominator becomes progressively harder to keep open."]'::jsonb, 2, 'Net pressure matching works precisely because the two models disagree so loudly about the direction.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 13, 'Look at what the geometry routine validates and what it computes. Where does fracture height come from?', '["You type it in, so it appears on the right hand side of every expression and never on the left.", "It is solved from the stress profile.", "It is derived from the perforated interval length once the closure stress and the plane strain modulus are known.", "It is returned as an output alongside the two widths."]'::jsonb, 0, 'That is the defining assumption of a two dimensional model rather than a limitation the engine could remove.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 14, 'Halve the assumed fracture height and hold everything else fixed. What happens to the PKN width and the PKN net pressure?', '["Both quantities double.", "The width does not move at all, while the net pressure doubles, because the same width now sits over half the height.", "The width is untouched since no height appears in its bracket, and the net pressure doubles because height divides it directly.", "The width halves and the net pressure is unchanged, since PKN carries the height inside the width bracket instead."]'::jsonb, 1, 'Fracture volume and leaking area both scale with height directly, so they halve alongside it.'),
  ('stimulation', 'intermediate', 'module', 'm03-width-net-pressure-and-height', 15, 'The module calls contained height a fiction. What check does it ask you to run outside the engine?', '["Whether the perforated interval matches the assumed height.", "Whether the model coefficients suit the fluid system.", "Whether the bounding formations carry a minimum stress higher than the pay by more than the predicted net pressure.", "Whether the injection rate stays inside the fracture extension pressure limit for the whole of the pumping schedule as designed."]'::jsonb, 2, 'Height runs first and length falls short, so a two dimensional half-length is a starting point to bracket rather than a length to quote as measured.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 1, 'In Carter''s model, how does the leakoff velocity at a point on the fracture face vary with the time that point has been exposed to fluid?', '["It holds a constant value for as long as the job keeps pumping.", "It rises in direct proportion to exposure time, because the invaded zone keeps deepening and draws more fluid as the job runs.", "It equals the leakoff coefficient divided by the square root of the exposure time at that point.", "It falls in inverse proportion to the exposure time, so the loss stops growing almost as soon as pumping starts."]'::jsonb, 2, 'Filter cake, invaded zone and the compressible reservoir ahead of it all thicken as the square root of time, which is why the velocity thins the same way.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 2, 'What does the factor of two in the lost volume expression KL CL (2 Af) sqrt(ti) account for?', '["Af is the area of one face, so the two brings in the second face of the fracture that also leaks.", "It counts the two wings of the fracture either side of the well.", "It doubles the leakoff coefficient, because Carter wrote his derivation for a single wing of a fully contained fracture.", "It converts the half-length used inside the area to the full tip to tip length of the fracture."]'::jsonb, 0, 'Both wings are already inside Af, so the two is purely about faces rather than about wings.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 3, 'With a half-length of 150 m and a height of 30 m, what leaking area does the published case present to the formation?', '["4500 m2, which is the half-length multiplied by the height.", "9000 m2, counting one face on each of the two wings, on the grounds that only the wall facing the reservoir accepts fluid.", "36000 m2, using the full tip to tip length of 300 m across both faces of both wings.", "18000 m2, being two faces on each of two wings, so 2 times 2 times 150 times 30 in metres squared."]'::jsonb, 3, 'That area is what the leakoff coefficient multiplies, so a taller or longer design raises the loss before any other effect appears.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 4, 'What units does the leakoff coefficient carry, and what value does the published case use?', '["Cubic metres per second, and the case uses 0.053 of them.", "Metres per square root of a second, with 0.0001 m/sqrt(s) taken as the value for the published case.", "Square metres per second, and the case uses 0.0001, since the coefficient is a diffusivity for the invaded zone ahead of the face.", "Metres per second, since it is a velocity through the wall, and the case uses 0.0001."]'::jsonb, 1, 'The odd unit follows from the definition, because the coefficient multiplies a square root of time to give a length of fluid lost per unit area.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 5, 'Why can the leakoff coefficient not simply be looked up as a rock property before a job?', '["Published tables of the coefficient were withdrawn as unreliable.", "It combines the fluid, the filter cake and the formation, so on a real well the value has to be measured.", "It changes with depth in a way that no laboratory apparatus can reproduce, which is why only the drilling record can supply it.", "It is a pure fluid property, so the service company supplies it with the gel."]'::jsonb, 1, 'The measurement is made by pumping a small volume and matching the pressure decline after shut in.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 6, 'Which loss mechanism does this material balance leave out, and where does that omission become unsafe?', '["Loss through the fracture tip, which matters only in shale.", "Loss to natural fractures crossing the face, which becomes unsafe whenever the reservoir carries a well developed joint set.", "Spurt loss, the slug taken before any filter cake exists, which matters in high permeability rock.", "Loss back to the wellbore during shut in, which is unsafe if the well is flowed back too early."]'::jsonb, 2, 'Where spurt is real the pad has to be larger than this model asks for, and the engine states the omission in its own documentation.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 7, 'What problem is the Nolte factor there to correct?', '["Parts of the face have been open for different lengths of time, so one exposure time cannot serve.", "It corrects the leakoff coefficient for the fluid temperature.", "It corrects the fracture area for the difference between the dynamic width during pumping and the width remaining after closure.", "It rescales the pump time so that the quadratic can be solved without any iteration."]'::jsonb, 0, 'The factor replaces an honest integral over a growing face with a single multiplier on the simple answer.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 8, 'Between which two limits does the Nolte factor sit across the whole range of efficiency?', '["Between zero and one, since the factor is itself a fraction.", "Between one and three, widening steadily as the fracture lengthens, which is why a long job needs a much larger correction.", "Four thirds at an efficiency of one, rising to half of pi as efficiency approaches zero at the other end.", "Between pi over five and pi over four, the two shape factors that the width models use."]'::jsonb, 2, 'Since the expression is linear in efficiency, the tabulated values fall on a straight line between those two endpoints.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 9, 'Why is the Nolte correction larger at low efficiency than at high efficiency?', '["Area then grows nearer the square root of time, so most of the face is old and has been leaking longer.", "A low efficiency job is pumped at a higher rate throughout.", "A low efficiency job gives a narrower fracture, and a narrow fracture offers more surface for every cubic metre of fluid stored.", "The leakoff coefficient itself rises as efficiency falls, and the factor carries that rise through."]'::jsonb, 0, 'When nothing leaks off, area instead grows in proportion to time, so the face stays young and needs the smallest correction.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 10, 'Given how narrow its range is, what should you conclude about the Nolte factor as a source of error?', '["It dominates the error, so it should be measured on every site.", "It carries much the same uncertainty as the coefficient, so the two are best calibrated together against the decline after shut in.", "It is exact, so a mismatch against a measured pump time must come from the injection rate.", "Uncertainty does not live there, because the leakoff coefficient itself can be wrong by a factor of two."]'::jsonb, 3, 'Its real significance is structural, since the factor needs efficiency and efficiency is one of the things the balance is trying to find.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 11, 'How is fracture efficiency defined, and roughly where does it sit on the published job?', '["Fracture volume over injected volume, near 0.1728566723633056, so about one part in six stays behind.", "Lost volume over injected volume, which comes to about one sixth.", "Fracture volume over lost volume, which lands near five on this job, since far more fluid enters the rock than the crack.", "Injected volume over fracture volume, which is 5.7851397133124625 on this job."]'::jsonb, 0, 'A treatment on those numbers is better read as a leakoff operation that leaves a fracture as its residue.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 12, 'Of the 209.09714590747427 m3 injected on the published case, where does the fluid end up?', '["Every cubic metre stays in the fracture until flowback begins.", "Roughly seven tenths remains in the fracture while the rest is lost, which is why the pad is set at that same fraction.", "36.143836842230584 m3 stays in the fracture and 172.95330906524367 m3 goes into the formation.", "Half is stored and half is lost, which is the neutral guess the engine starts its iteration from."]'::jsonb, 2, 'The fracture volume is unchanged across the whole leakoff sweep, since only the fluid needed to reach it moves.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 13, 'Which expression gives Nolte''s pad fraction, and what does it come to on the published case?', '["Simply one minus eta, giving 0.8271433276366944 on this job.", "One minus eta over one plus eta, which gives 0.7052381992848291 at the published efficiency.", "The efficiency itself, so about a sixth of the job is pad while the remaining fluid carries proppant from the first minute.", "Eta over one plus eta, which puts the pad a little under a sixth of the total volume."]'::jsonb, 1, 'The intuitive guess of the lost fraction overstates the pad by 0.12190512835186529 here, and that gap is widest in the middle of the efficiency range.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 14, 'Why does the pump time equation have to be solved as a quadratic rather than by division?', '["Because the injection rate is varied in steps through the job.", "Because two fracture volumes satisfy the balance, and the engine has to select the one giving a positive net pressure.", "Because the Nolte factor multiplies the rate, which makes the balance nonlinear in rate.", "The unknown appears both linearly and under a root, so the balance is a quadratic in the root of time."]'::jsonb, 3, 'Having solved for the square root of time, the engine keeps the positive root and squares it.'),
  ('stimulation', 'intermediate', 'module', 'm04-material-balance', 15, 'By what procedure does the engine converge the material balance, and what did the published case need?', '["A single closed form expression is evaluated once, with no iteration.", "A guess of 0.5 for efficiency is refined until it settles, which took 9 passes on the published case.", "The leakoff coefficient is swept over a table of values and interpolated, which is why the digest reports a sweep.", "A guess of one for efficiency is stepped down, reaching the answer after the full 200 passes."]'::jsonb, 1, 'The loop contracts quickly because the Nolte factor barely moves across the efficiency range, and it gives up after 200 passes.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 1, 'Which of the three dimensions do PKN and KGD both declare known in advance, and why do they do it?', '["Width, because elasticity already fixes it once the net pressure is known.", "Height, because fixing it is what buys a closed form in place of a mesh and a solver.", "Length, because the operator specifies the target half-length before the job and the model has no reason to solve for it.", "Depth, because the perforated interval is surveyed and needs no calculation."]'::jsonb, 1, 'Solving the problem properly means coupling an elastic surface of unknown shape to a fluid flow problem on that same surface.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 2, 'What does PKN treat as uniform, and which length scale sets its compliance?', '["Each vertical slice is rigid, so the width is uniform along the length.", "Every horizontal plane acts as an isolated Griffith crack in plane strain, so it is the half-length that fixes the compliance.", "The net pressure is uniform, so the wellbore pressure alone sets the width.", "Each vertical cross section acts as an isolated slice in plane strain, so height sets the compliance."]'::jsonb, 3, 'That assumption is a bet that the fracture is long and contained, which is the opposite bet to the one KGD makes.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 3, 'In KGD, what role is left to the height once the geometry has been assumed?', '["It is only somewhere to put the fluid, since width is set by the half-length through the horizontal planes.", "It sets the compliance, exactly as it does in PKN.", "It is solved for, because KGD is the model that allows the fracture to find its own vertical extent as it grows.", "It fixes the net pressure through a plane strain slice taken across the fracture."]'::jsonb, 0, 'KGD suits a short fracture, where treating each horizontal plane as a Griffith crack is the more defensible fiction.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 4, 'Given the same rock, fluid, rate and height, what happens to the gap between KGD and PKN average width as the fracture lengthens?', '["It closes, since both models converge once the fracture is long.", "It stays fixed at the ratio of the two shape factors, because the only real difference between the models is how each averages its width profile.", "It widens, from a factor of 1.8723566993895047 at a half-length of 40 m to 3.0985171538556986 at 300 m.", "It reverses, so PKN gives the wider fracture beyond a half-length of about 100 m."]'::jsonb, 2, 'That growing disagreement is the missing third dimension making itself felt, since one fiction becomes more defensible while the other becomes less so.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 5, 'What do the shape factors of pi over five and pi over four actually represent?', '["They are empirical fudge factors fitted to field treating pressures.", "They convert the maximum width into a volume by accounting for the two wings.", "Each is the integral of a width profile along a fracture that the model itself never troubles to compute.", "They are the last visible trace of the geometry that was assumed away, being averages over a profile neither model solves for."]'::jsonb, 2, 'PKN averages with pi over five and KGD with pi over four, so the choice of model alone moves the stored volume.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 6, 'For a fracture whose height and half-length are similar, why is neither model safe to trust?', '["Neither dimension is then small enough to be treated as uniform, so both bets about the geometry fail.", "Both models are safe there, because their answers agree at that aspect ratio.", "The rock is too stiff at that aspect ratio for plane strain to apply at all, so elasticity itself has to be abandoned.", "The leakoff coefficient becomes undefined once the two dimensions are comparable."]'::jsonb, 0, 'Each model is a bet about which dimension is small enough to be treated as uniform, and a square fracture loses both bets at once.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 7, 'What does the engine actually do with the fracture height that a user types in?', '["It compares the height against the perforated interval and warns if the two disagree.", "It checks only that the value is positive, then carries it into every line of the design that follows.", "It refines the height during the iteration, since the material balance already carries enough information to correct a poor first estimate.", "It rescales the height once net pressure is known, which is why the reported height can differ."]'::jsonb, 1, 'On the published case the height is 30 m while the perforated interval runs from 2450 m to 2550 m measured depth.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 8, 'If the fracture grew taller than designed, what would happen to the net pressure PKN reports?', '["It would rise sharply, since more rock has to be parted.", "It would not change, because net pressure in PKN is fixed by the fluid viscosity and the injection rate alone.", "It would fall only while the fracture remained inside the pay, and would then rise again once it entered a bounding shale layer.", "It would fall, since PKN divides maximum width by twice the height, so a taller fracture is more compliant."]'::jsonb, 3, 'That is why a treating pressure which stops rising should be read as a symptom rather than as a relief.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 9, 'Besides pressure, what else does unwanted height growth cost the treatment?', '["Length and efficiency, since volume put into height is lost to length while the leaking area also grows.", "Only proppant, because the same mass is spread more thinly.", "Nothing measurable, because the extra height contributes conductive fracture area that offsets the loss in half-length.", "Only pump time, since the larger volume takes proportionally longer to place."]'::jsonb, 0, 'The three effects reinforce each other, so the published efficiency of 0.1728566723633056 would fall at the same time as the length shortens.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 10, 'Which live measurement warns that a fracture has found somewhere else to go during pumping?', '["The surface rate, which drops as soon as height growth begins.", "The proppant concentration returning at surface, since a fracture that has grown out of zone starts to flow back part of its slurry.", "The slope of net pressure against time on log scales, which flattens or turns down at steady rate.", "The slurry density, which rises once the fracture reaches a bounding layer."]'::jsonb, 2, 'Containment is a stress question first, and afterwards the created height is logged with tracer, temperature, microseismic or tiltmeter surveys.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 11, 'Why will the engine not accept a rock toughness as an input?', '["Toughness never enters either model, since width comes from elasticity and viscous flow rather than strength.", "Toughness is already folded into the leakoff coefficient.", "Toughness is a laboratory quantity that cannot be measured downhole, so the engine deliberately excludes it from the design workflow.", "Toughness only matters during closure, which is outside the pumping calculation."]'::jsonb, 0, 'Linear elastic fracture mechanics treats that cost as a stress intensity the fluid must supply, which acts as a floor on net pressure the models lack.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 12, 'Which two further pieces of tip physics sit alongside toughness among the missing effects?', '["Turbulence at the tip, and heat generated by the parting rock.", "Spurt loss into the tip, and the settling of proppant against the crack front.", "Dilatancy in the damaged rock near the tip, and the unwetted lag region ahead of the fluid front.", "Dilatancy in the damaged rock at the tip, together with a lag region ahead of the fluid front that sits at very low pressure."]'::jsonb, 2, 'The lag matters because the loading is then not the uniform pressure that the closed forms assume.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 13, 'What does the KGD net pressure falling from 1166434.0645127255 Pa at 40 m to 425921.49931737053 Pa at 300 m actually tell you?', '["That KGD is the more accurate model for long fractures.", "That the leakoff coefficient has been set too low, because a properly leaky rock would hold the net pressure up as the fracture lengthens.", "That the fracture has begun to grow in height, which relieves pressure.", "That compliance alone is setting the pressure, since no real tip propagates on a vanishing net pressure."]'::jsonb, 3, 'Field net pressures routinely exceed both published figures, and that excess is missing physics rather than arithmetic error.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 14, 'How is the shortfall between modelled and measured net pressure handled in practice?', '["By switching from PKN to KGD, whichever fits the measurement.", "By calibration, pumping a minifrac or step rate test and carrying an apparent property or a multiplier.", "By raising the closure stress in the model until the predicted treating pressure matches what the pumps are reading at surface.", "By adding a toughness term to the width equation before the main treatment."]'::jsonb, 1, 'The multiplier is a confession that physics is missing, and an honest one, since it absorbs a difference the model cannot explain.'),
  ('stimulation', 'intermediate', 'module', 'm05-where-the-models-stop', 15, 'What does the conversion of proppant mass into a propped fracture assume about where the grains are?', '["That the grains settle into a bank across the lower part of the fracture.", "That the proppant occupies only the part of the fracture created before the pad has been fully spent, which is where the width is greatest.", "That the mass sits everywhere at one areal loading, from wellbore to tip and from the top to the bottom.", "That the grains are distributed in proportion to the local width, so the wide region near the wellbore carries most of the mass."]'::jsonb, 2, 'Settling and bridging both break it, so the propped half-length is usually shorter than the created half-length and the propped height is less than the created height.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'A graduate joining your team asks you to compress the whole Professional tier into a single sentence before her first design review. Which sentence would you give her?', '["A fracture is a pressure problem with a fixed height, and every closed form here was bought by fixing something at a stated price.", "A fracture is a volume problem, so the balance settles everything else.", "A fracture is an elastic problem whose width follows from the rock alone, so the treatment schedule only decides how quickly that width is reached.", "A fracture is a strength problem, and the toughness of the rock at the tip decides the geometry."]'::jsonb, 0, 'Read against that sentence the five modules stop being five topics and turn into one argument.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'During a review a colleague argues that the job will come out wider if the fleet simply opens the pumps up. How much wider, and is rate the lever he thinks it is?', '["Width rises in proportion to rate, so doubling the rate doubles it.", "Width falls as rate rises, because a faster job leaves the face less exposure time and therefore less opportunity to leak fluid away.", "Sixteen times the rate buys twice the width, so the lever is real but far too weak to design around.", "Sixteen times the rate buys sixteen times the width, since rate sits at the first power inside the width bracket."]'::jsonb, 2, 'Rate does shorten the job almost in proportion, so it is a schedule lever rather than a width lever.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'You watch an engineer open the capstone by going straight for the two fracture widths. Which quantity did she skip, and why does its position in the order matter?', '["The leakoff coefficient, because the balance cannot start without it.", "The plane strain modulus, since every width and every net pressure downstream of it contains that one number.", "The plane strain modulus, because both width equations divide by it and its refusals are the first thing to trip when an input carries the wrong unit.", "The closure stress, because it must be subtracted before either width equation can be evaluated at all."]'::jsonb, 1, 'The routine refuses a Poisson ratio outside the open interval from zero to one half and refuses a modulus that is not positive.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'A design sheet crossing your desk lists a PKN average width and a KGD average width that agree to within three per cent. Which of the three checks has failed, and what does the agreement imply?', '["The volume check, and it means the stored volume was computed on the maximum width.", "No check has failed, because the two models are expected to converge once the fracture is long relative to its own height.", "The efficiency check, and it means the fixed point stopped on its first pass rather than converging properly on the published tolerance.", "The disagreement check, and it means one expression was evaluated twice rather than two different models being run."]'::jsonb, 3, 'In the digest sweep the ratio runs from 1.8723566993895047 at a half-length of 40 m up to 3.0985171538556986 at 300 m.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Someone hands you a completed balance quoting an efficiency of 1.14. What has gone wrong, and what is the only condition under which the number may touch its upper limit?', '["The balance was never solved, and efficiency reaches exactly one only where the leakoff coefficient is zero.", "Nothing is wrong, because efficiency above one simply signals a low leakoff fluid.", "The Nolte factor was left out of the quadratic, and efficiency may reach one whenever the pump time is short enough for the face to stay young.", "The pad fraction was subtracted twice, and efficiency touches one at the published pump time."]'::jsonb, 0, 'That zero leakoff limit is the case the engine returns in no iterations at all, at a pump time of 681.9591857024639 s.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'A trainee''s sheet shows a fracture volume larger than the volume he says was injected. Explain to him why that ordering can never occur.', '["Because the fracture stores fluid at a higher pressure than the pumps deliver.", "Leakoff only ever removes fluid from the fracture, so injected volume has to exceed stored volume on every job.", "Leakoff only ever takes fluid away, so what went into the ground can never be less than what stayed behind in the crack itself.", "Because the two wings are counted separately in one of the two volumes and only once in the other."]'::jsonb, 1, 'On the published case that comparison is 209.09714590747427 m3 injected against 36.143836842230584 m3 stored.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'An intern computes a PKN maximum width, then divides it by four times the half-length to get his net pressure. Why is this the error the tier warns about most loudly?', '["Because four times the half-length is only valid once the pad has been placed.", "Because the KGD compliance needs the average width rather than the maximum.", "He has mixed the length scales, and the resulting figure looks perfectly reasonable rather than announcing itself.", "Because each model has to take net pressure from its own length scale, PKN dividing by twice the height and KGD by four times the half-length."]'::jsonb, 2, 'At the published conditions the two net pressures differ by a factor near five, and they also move in opposite directions with length.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'A contractor runs the material balance on the maximum width because it is the number quoted at the top of his output. What has that done to the design?', '["It has inflated the stored volume, because volume is two wings times height times the AVERAGE width, not the peak.", "It has done nothing, since both models average with the same shape factor.", "It has deflated the stored volume, because the maximum width is always the smaller of the two numbers the geometry routine returns.", "It has inflated the leaking area instead, because the area term carries the width through the two faces of the two wings."]'::jsonb, 0, 'The maximum width earns its keep elsewhere, deciding whether a slurry will bridge as it passes the wellbore.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'To save an hour, a designer picks PKN on geometric grounds and never runs KGD at all. What has he given up by skipping the second run?', '["The average width, which only the KGD branch of the routine returns.", "Nothing at all, because the rule of thumb is unambiguous whenever the half-length is several times the height.", "The closure stress, because each model reads a different depth from the stress profile before it computes anything else.", "The measure of what his choice was worth, since only the other model tells him how much the assumption moved the answer."]'::jsonb, 3, 'Computing both is also what arms the disagreement check, which cannot be applied to a single result.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'A capstone submission comes back with the geometry routine throwing before it returns anything. Which two refusals should you look for first, and what usually causes them?', '["A missing closure stress and a model name the routine cannot recognise.", "A non-positive modulus and a Poisson ratio outside zero to one half, almost always caused by a unit slip.", "A modulus that is not positive and a Poisson ratio outside the open interval from zero to one half, which is what a value entered in field units rather than strict SI produces.", "A negative leakoff coefficient and an efficiency guess that started outside the range."]'::jsonb, 1, 'Working in metres, pascals, pascal seconds and cubic metres per second throughout is what keeps those refusals quiet.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'A capstone case describes a short fracture with a half-length comparable to its height and no strong stress contrast above or below. Which model applies, and what has to travel with the choice?', '["PKN, with no justification needed, since PKN is the industry default.", "Whichever model gives the narrower width, so that the design errs on the side of caution.", "KGD, together with the stated reason for choosing it, because the choice of model is where the engineering sits.", "KGD, and no reasoning is required, because the routine already refuses any pairing of model and geometry that it considers unsound."]'::jsonb, 2, 'The contained case with a half-length several times the height is the other branch of the same rule of thumb.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Your manager asks, plainly, what this tier now qualifies you to do on a fracture design. Which claim is the honest one?', '["Set net pressure above closure, run both width models with their opposing pressure trends, and converge a material balance.", "Design the pad, the proppant ramp and the conductivity of the finished pack.", "Predict fracture height from the stress profile and follow it as the treatment proceeds.", "Quote a propped half-length and the skin it produces, since the width and the balance between them already fix what the well will deliver."]'::jsonb, 0, 'The pad, the ramp, the pack and the skin all sit in the Expert tier, downstream of exactly this geometry.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'A client wants the pad fraction and a stepped proppant ramp for the blender. Which single result from this tier do those calculations wait on?', '["The maximum width, because the pad has to be wide enough to accept grain.", "The plane strain modulus, because the pad is sized from the stiffness of the rock and the rate at which the fluid enters it.", "The closure stress, since the pad is pumped until the fluid pressure first exceeds it.", "The efficiency out of the material balance, since how much of the treatment is pad follows from efficiency alone."]'::jsonb, 3, 'On the published case that efficiency is 0.1728566723633056, and proppant entering a fracture not yet created is proppant that bridges.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'A partner''s report quotes a half-length of 150 m and stops there. What must sit beside that figure before it counts as a design rather than a number?', '["The bottomhole treating pressure and the rate the fleet can sustain.", "The model that produced it, the height that was assumed, and the efficiency the balance converged on.", "The model behind it, the assumed fracture height and the efficiency, since without all three the reader cannot tell what was fixed or what the fixing cost.", "The proppant type and the pump schedule, because those are what a service company prices the job from."]'::jsonb, 1, 'That habit of naming the fixed thing and then naming its price is what the tier asks you to carry forward.'),
  ('stimulation', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'Before starting the Expert tier a team assumes it will repair the limits catalogued in module five. Is that expectation correct?', '["Yes, because a three dimensional treatment of height growth is exactly what comes next.", "Yes, because calibrating against a minifrac in the Expert tier removes the need for any of those assumptions.", "No, since height stays fixed, tip physics stays absent and proppant is still spread uniformly across the face.", "No, because the extra work of the Expert tier happens downstream of the same geometry, so every limit listed in module five is carried forward unchanged."]'::jsonb, 2, 'That is why the limits have to be carried forward alongside the method rather than quietly dropped once the pack is added.'),
  ('stimulation', 'intermediate', 'final', null, 1, 'A revised stress profile raises the closure figure by 2 MPa while the PKN geometry stays exactly as it was. Which outputs move?', '["Both the net pressure and the treating pressure climb by 2 MPa.", "Net pressure drops by 2 MPa, because the fluid pressure inside the fracture is fixed and the surplus over closure shrinks.", "Bottomhole treating pressure rises by that same 2 MPa, and the net pressure set by the geometry does not move.", "Only the widths respond, since closure enters the width bracket through the plane strain modulus."]'::jsonb, 2, 'Closure is the large fixed contribution from the earth and it reaches treating pressure one for one, with no damping at all.'),
  ('stimulation', 'intermediate', 'final', null, 2, 'Perforations sit between 2450 m and 2550 m on a deviated well, and a colleague looks the stress up at the 2500 m mid point. What has he done?', '["He has taken the stress more than three hundred metres too deep, since the mid perforation vertical depth is 2124.897478 m.", "Nothing of consequence, as stress is read against measured depth.", "He has understated closure, because a deviated hole always crosses the pay at a shallower vertical position than the driller records.", "He has moved the fracture plane, which now opens against the vertical stress rather than the minimum horizontal one."]'::jsonb, 0, 'Overburden and pore pressure act at a vertical position, so every stress lookup in the tier takes true vertical depth.'),
  ('stimulation', 'intermediate', 'final', null, 3, 'An analyst feeds 25 GPa straight into the width bracket in place of the 27.126736 GPa the tier calls for. How does the answer come out?', '["Too narrow, since a softer rock always yields a thinner fracture.", "Slightly too wide, by roughly a quarter of the nine per cent gap, and computed with coefficients that no longer belong to it.", "Wider by nine per cent, because width tracks the stiffness in the denominator in direct proportion rather than through any root.", "Unchanged, as the two moduli cancel between the width and the net pressure."]'::jsonb, 1, 'The published coefficients 2.31 and 3.22 were derived with the plane strain modulus, so substituting Young''s modulus breaks the formula rather than the rock.'),
  ('stimulation', 'intermediate', 'final', null, 4, 'Two beds at the same depth on one well carry noticeably different minimum horizontal stress. What accounts for that, and why should a designer care?', '["Nothing accounts for it, so one of the two readings is a bad measurement.", "The deeper bed is always the stiffer of the two, and stiffness alone raises the stress it can carry, which is why gradients rise smoothly with depth.", "Only the fluid in the pore space matters, so the difference disappears once both beds are drawn down to the same pressure.", "Stiffness, pore pressure and tectonic history differ bed to bed, and the contrast above the pay is what holds the height in."]'::jsonb, 3, 'That is why the stress profile is the deliverable and a single number pulled from it is only the value at one depth.'),
  ('stimulation', 'intermediate', 'final', null, 5, 'A capstone run stops before returning anything, and the input sheet lists a Poisson ratio of 0.5. Why did it refuse?', '["An incompressible ratio sits outside the open interval from zero to one half, so no admissible stiffness could be returned.", "The routine accepts only ratios that match a named lithology.", "A ratio of exactly 0.5 makes the numerator vanish, so the plane strain modulus would come back as zero rather than as a usable stiffness.", "It refused the modulus instead, because 25 GPa is too small for the coefficients that follow it."]'::jsonb, 0, 'Above one half the elastic constants are inadmissible, so there is nothing sensible for the routine to hand back.'),
  ('stimulation', 'intermediate', 'final', null, 6, 'PKN and KGD are run on one well and report 41.021687 MPa and 38.734295 MPa of treating pressure. Where does the 2.29 MPa gap come from?', '["From the difference in the closure each model assumes.", "From the pipe and perforation friction, which PKN carries in its treating pressure and KGD leaves out of scope entirely.", "Entirely from net pressure, because both rows share the closure of 38.13195 MPa and only the model changes it.", "From the plane strain modulus, since each model applies its own correction to Young''s modulus before working out the width."]'::jsonb, 2, 'Both figures are bottomhole numbers, with slurry hydrostatic and friction put explicitly out of scope by the engine.'),
  ('stimulation', 'intermediate', 'final', null, 7, 'Someone argues that a very soft shale would show a huge gap between Young''s modulus and the plane strain modulus. Is that possible?', '["Yes, the gap grows without limit as the rock becomes softer.", "No, since the denominator bottoms out at 0.75, so the plane strain modulus can never exceed four thirds of Young''s modulus.", "No, because the correction depends on the modulus itself rather than on the Poisson ratio, and a soft rock therefore needs no correction at all.", "Yes, but only below a Poisson ratio of 0.28, where the factor starts to run away."]'::jsonb, 1, 'For ordinary sandstones and carbonates the correction stays in the region of a few per cent, which the fourth root damps further still.'),
  ('stimulation', 'intermediate', 'final', null, 8, 'Thick strong shales bound a pay zone and the design aims for a half-length five times the height. Which model applies, and what should the pressure record do?', '["KGD applies, and the record should fall steadily.", "PKN applies, but its net pressure should fall as the job proceeds, because a longer fracture is a more compliant one in every model.", "Either model serves, since both predict the same trend once the barriers are known to be holding.", "PKN applies, and its net pressure should climb through the job as the fracture lengthens against a fixed height."]'::jsonb, 3, 'Contained height with a fixed compliance length is exactly the condition under which net pressure matching against PKN is meaningful.'),
  ('stimulation', 'intermediate', 'final', null, 9, 'A crew builds its slurry schedule around 10.463769 mm of average width on a well whose rock is behaving as PKN. What arrives at the perforations?', '["Concentrations sized for a fracture two and a half times fatter than the 4.015982 mm the well can actually offer.", "A schedule that is safe, because the extra width is a margin.", "A schedule that will simply place less proppant per unit length, since the fracture takes what it can hold and returns the remainder to surface.", "A schedule that is too lean, because the KGD width understates what a contained fracture opens to."]'::jsonb, 0, 'Bridging risk is set by the narrowest part the grains have to pass, so an overstated width shows up as a screenout rather than as a mild error.'),
  ('stimulation', 'intermediate', 'final', null, 10, 'Every treatment begins shorter than it is tall and ends far longer than it is tall. What does that do to the practice of naming one model for the job?', '["Nothing, because the early seconds place too little fluid to matter.", "It means the rule of thumb should be applied to the height alone, as the height is the only dimension that stays fixed while the job runs.", "It guarantees the choice is wrong at one end, since the early fracture is KGD territory and the late one is PKN territory.", "It means the two models should be run in turn and the results added, so that each covers the part of the job it owns."]'::jsonb, 2, 'Nothing in either model announces its own failure, so the crossover has to be judged rather than detected.'),
  ('stimulation', 'intermediate', 'final', null, 11, 'A colleague proposes averaging the PKN and KGD widths so that the design hedges the model choice. What is wrong with that?', '["Nothing is wrong, provided the two are weighted by half-length.", "They are different elastic problems rather than two approximations either side of a truth, so the answer need not lie between them.", "The average would be too narrow, because the mean of the two widths always falls below the smaller of them once the shape factors are applied.", "Averaging is fine for width but not for net pressure, since only the pressures carry opposite slopes."]'::jsonb, 1, 'Neither model conserves anything the other does, which is why interpolating between them has no meaning.'),
  ('stimulation', 'intermediate', 'final', null, 12, 'A junior asks why the software let him run KGD on a fracture five times longer than it is tall. What is the answer?', '["The routine cannot know which of the two geometry numbers you trust, so it checks only for positive inputs and a known model name.", "It does refuse that pairing, so his run must have failed silently.", "It allows the pairing because KGD is the conservative choice, and the engine defaults to the model that reports the wider fracture.", "It allows any pairing where the half-length exceeds the height, and refuses the reverse."]'::jsonb, 0, 'A refusal on the pairing would mean the engine had decided which of your inputs was the reliable one, which it is in no position to do.'),
  ('stimulation', 'intermediate', 'final', null, 13, 'Dividing the two published maximum widths gives about 2.08, yet the average widths stand at 2.605532 apart. What closes that gap?', '["Rounding in the maximum widths, which are quoted too coarsely.", "The plane strain modulus, which enters the average width but not the maximum, so the two ratios were never going to agree.", "The half-length, which appears squared in one average and not in the other.", "The shape factors, since KGD averages with pi over four and PKN with pi over five, adding a further five to four."]'::jsonb, 3, 'PKN tapers twice, across the height and towards the tip, so it keeps a smaller share of its own maximum than KGD does.'),
  ('stimulation', 'intermediate', 'final', null, 14, 'Net pressure on a live job is drifting downwards while the rate holds steady. Which two readings does the tier offer for that?', '["The fluid has thinned, which is the only cause of a falling trend.", "The closure stress is falling as the reservoir is drawn down, which lowers the surplus even though the fluid pressure has not moved at all.", "The well is behaving as KGD, or the fracture is growing in height and relieving its own pressure.", "The pad has run out, so the record has switched from the width trend to the proppant trend."]'::jsonb, 2, 'Both readings share a consequence, which is that a design built on a rising PKN trend was reading the record backwards.'),
  ('stimulation', 'intermediate', 'final', null, 15, 'A fleet on location can double the injection rate. What does that buy in PKN width, and what does it buy in pump time?', '["Width doubles and pump time halves, since both go with rate.", "Width rises only by the fourth root of two, while the pump time shortens close to proportionally with the rate.", "Width rises by the fourth root of two and pump time is untouched, because the leakoff term grows exactly as fast as the injection term does.", "Width falls slightly and pump time halves, as the faster job gives the fracture less time to open."]'::jsonb, 1, 'That asymmetry is why rate is a schedule lever rather than a width lever on a real design.'),
  ('stimulation', 'intermediate', 'final', null, 16, 'Your fluid characterisation turns out to have been wrong by a factor of eight on viscosity. How far does that error reach into the width?', '["Less than a factor of two, because viscosity sits inside the same bracket and the quarter power damps it heavily.", "A factor of eight, since viscosity enters the bracket linearly.", "A factor of about three, since the quarter power applies to the rate and the half-length but leaves the viscosity term untouched.", "None at all, because viscosity affects only the leakoff and never the geometry."]'::jsonb, 0, 'The same damping that forgives a poor fluid characterisation is what refuses to reward a good one.'),
  ('stimulation', 'intermediate', 'final', null, 17, 'A KGD run is repeated with the fracture height doubled and nothing else altered. Which way do its outputs go?', '["Width is unmoved, since KGD takes no height in its bracket.", "Width doubles and net pressure halves, because the extra height offers more room for the same injected rate to open the rock.", "Width falls while net pressure rises, since KGD divides by the height when it converts width into pressure.", "Width falls, because height sits in the denominator under the quarter power, and net pressure follows the width down."]'::jsonb, 3, 'Fracture volume and leaking area both scale directly with height, so the balance downstream moves even where the elasticity barely does.'),
  ('stimulation', 'intermediate', 'final', null, 18, 'Logs put the bounding shales barely 1 MPa above the pay in minimum stress while the PKN net pressure comes out at 2.889736 MPa. What follows?', '["Nothing follows, since containment is a stiffness question.", "The fracture stays contained, because net pressure acts along the length of the fracture and never across the barrier at the top and bottom.", "The surplus exceeds the contrast, so the fracture will not stay in the 30 m assumed and the designed half-length is optimistic.", "The design is safe once the pad is enlarged, as extra clean fluid lowers the pressure at the boundary of the pay."]'::jsonb, 2, 'That comparison lives in the geomechanics work rather than in the engine, which has no way of testing the height it was handed.'),
  ('stimulation', 'intermediate', 'final', null, 19, 'A reviewer reads only the last page of a design and sees a skin. How far upstream can a wrong fracture height reach?', '["All the way, through volume and leaking area to pump time, pad, proppant mass, propped width and the conductivity behind that skin.", "Only as far as the net pressure, which is where height enters.", "Not at all, because the productivity calculation works from the propped half-length and takes no height of any kind as an input.", "As far as the widths, after which the material balance normalises the error away."]'::jsonb, 0, 'One unchecked entry at the top of the chain is worth saying out loud to anyone who reads a design backwards.'),
  ('stimulation', 'intermediate', 'final', null, 20, 'The published PKN case stores 36.143836842230584 m3 of fracture. Which arithmetic on the widths produced that figure?', '["The maximum width multiplied by the face area of one wing.", "Two wings multiplied by the half-length, the height and the average width, so 2 xf hf w_avg rather than the maximum.", "The average of the PKN and KGD widths multiplied by the leaking area, since the volume has to be consistent with the loss term beside it.", "The average width multiplied by the full tip to tip length and the height."]'::jsonb, 1, 'Everything downstream, the pump time, the efficiency, the pad and the proppant mass, is built on that one product.'),
  ('stimulation', 'intermediate', 'final', null, 21, '20/40 ceramic has to travel a fracture that PKN puts at 4.015982 mm average and KGD at 10.463769 mm average. Which width governs the bridging risk?', '["The average width governs it, since grains meet the mean opening.", "Neither, because bridging is decided by the proppant concentration in the slurry rather than by any dimension of the fracture itself.", "The propped width governs it, as that is what the grains occupy once the job has finished.", "The maximum width near the well governs it, and the model choice matters because the two disagree by 2.605532 on the same rock."]'::jsonb, 3, 'Grains arch and stop once the opening narrows to a few grain diameters, and everything behind them stops with them.'),
  ('stimulation', 'intermediate', 'final', null, 22, 'Switching to a cheaper fluid doubles the leakoff coefficient from 0.0001 to 0.0002. Why is the damage worse than proportional?', '["It is not worse than proportional, only the volume doubles.", "The coefficient enters the lost volume squared, so doubling it quadruples the loss and the injected volume follows that same square law.", "The extra loss lengthens the job, and a longer job leaves the face exposed for longer, so the loss feeds itself.", "The Nolte factor doubles alongside the coefficient, which multiplies the two effects together."]'::jsonb, 2, 'Efficiency falls to less than a third on that step while the injected volume more than triples.'),
  ('stimulation', 'intermediate', 'final', null, 23, 'A run reports 46688.88701504819 s of pumping with 97 per cent of it as pad. How should that number be read?', '["As a design signal rather than a schedule, since more than half a day of pumping to place 36 m3 is a failed design.", "As a normal outcome for a high leakoff formation.", "As an arithmetic fault in the quadratic, because a pump time beyond a day means the positive root was not the one taken.", "As a reason to raise the proppant concentration, so the job places its mass in less time."]'::jsonb, 0, 'Only one of the four available responses is pumping longer, and the other three change the design instead.'),
  ('stimulation', 'intermediate', 'final', null, 24, 'A design sheet quotes an efficiency, a pump time and an injected volume that do not satisfy one another. What has happened?', '["The tolerance was set too loosely on the iteration.", "Someone has edited one of the three by hand after the fact, since the loop returns a consistent set or nothing at all.", "The three were computed for different leakoff coefficients, which is expected whenever a sweep is run and only one row is quoted in the report.", "The quadratic was solved for the negative root, which throws the three quantities out of step."]'::jsonb, 1, 'Efficiency, pump time and injected volume satisfy each other by construction, so a set that fails to close is a real and common defect.'),
  ('stimulation', 'intermediate', 'final', null, 25, 'A case comes back having hit the 200 pass cap rather than converging in nine. What does that tell you?', '["The convergence tolerance is too tight and should be relaxed.", "The answer is still trustworthy, because the loop reports the last efficiency it computed and 200 passes is far more work than nine.", "The leakoff coefficient was set to zero, which is the case that never converges.", "The inputs sit somewhere the approximation was never meant to go, since the loop normally contracts fast."]'::jsonb, 3, 'Iteration counts are provenance, and the zero leakoff case is the exception that returns a closed form in no passes at all.'),
  ('stimulation', 'intermediate', 'final', null, 26, 'A colleague suggests fixing the Nolte factor at a constant to avoid iterating altogether. What would that cost and what would it gain?', '["It would gain nothing, as the factor does not enter the quadratic.", "It would cost most of the accuracy of the balance, because the factor is where the uncertainty in a material balance actually lives.", "Very little accuracy, since the factor never leaves four thirds to half of pi, and it would break the circle the loop exists to close.", "It would gain speed but return an efficiency above one, which the checks would then reject."]'::jsonb, 2, 'The narrow range is also why each pass changes the factor so little that nine of them were enough on the published case.'),
  ('stimulation', 'intermediate', 'final', null, 27, 'A designer sizes the pad as the fraction of fluid lost, which on the published job is 0.8271433276366944. How far out is he?', '["Too large by 0.12190512835186529, since Nolte''s expression gives 0.7052381992848291 rather than the fraction lost.", "Correct, as the two expressions agree at every efficiency.", "Too small, because the intuitive guess ignores the fluid that leaks off during the proppant stages and therefore undersizes the clean volume.", "Too large by a factor of two, which is the widest the two can ever be apart."]'::jsonb, 0, 'The gap between the two is widest in the middle of the efficiency range and closes at both ends of it.'),
  ('stimulation', 'intermediate', 'final', null, 28, 'Pumping the published job takes 3945.2291680655526 s against 681.9591857024639 s if nothing leaked off. What is that hour mostly buying?', '["Extra width, which the longer exposure at the face builds up.", "Fluid that will never be in the fracture, since leakoff has multiplied the job by 5.7851397133124625.", "The proppant ramp, because the ramp occupies the time between the no loss pump time and the full pump time on every job of this kind.", "Fracture length, since the fracture volume grows with the pump time."]'::jsonb, 1, 'More than four fifths of the pumping pays for the rock drinking, and the fracture is the residue rather than the object being filled.'),
  ('stimulation', 'intermediate', 'final', null, 29, 'Measured net pressure on site comes in at several times the 2.889736 MPa PKN figure. Is the arithmetic wrong or the rock unusual?', '["The arithmetic, since a factor of several cannot be physical.", "The rock, because only an unusually stiff formation can carry a surplus that far above what the elasticity solution allows for.", "The gauge, since the model reports a bottomhole number and the gauge reads at surface.", "Neither, because toughness, dilatancy and the unwetted tip are absent from the model and routinely lift the real pressure."]'::jsonb, 3, 'A measured pressure well above either published figure is the normal outcome, and the field handles it with a calibrated multiplier.'),
  ('stimulation', 'intermediate', 'final', null, 30, 'A report quotes the created half-length of a job as though it were the propped half-length. What has been assumed away?', '["Nothing, as the two lengths coincide once the pad is correct.", "Transport, since settling and bridging leave the propped length shorter and the propped height less than what was created.", "Only the pad, because clean fluid reaches the tip ahead of the slurry and the propped length is therefore longer than the created one.", "Leakoff, which shortens the created length before any proppant arrives."]'::jsonb, 1, 'The conversion of mass into a pack divides by the whole face at once, so both transport losses are invisible in this calculation.'),
  ('stimulation', 'intermediate', 'final', null, 31, 'A trainee plans to check his pack thickness against the 4.015982 mm PKN average width. Why will that mislead him?', '["Because the average width is quoted at the well rather than the tip.", "Because the average width belongs to KGD, and the PKN figure that should be compared with a pack is the maximum width instead.", "That is the dynamic width held open by the fluid, and the fracture closes onto the grains once pumping stops.", "Because the pack is thicker than the fracture, having been compressed during placement."]'::jsonb, 2, 'The width available for transport exists only while the job is live, which is why the propped width is always the smaller number.'),
  ('stimulation', 'intermediate', 'final', null, 32, 'The job is over and the team is arguing about how tall the fracture grew. What settles it?', '["Radioactive tracer and temperature logs show where the fluid went, and microseismic or tiltmeter surveys map the height directly.", "The final treating pressure, read against the design value.", "A rerun of the geometry at several heights, keeping whichever height reproduces the pump time that the job actually took to place.", "The proppant mass returned during flowback, which scales with the height that took slurry."]'::jsonb, 0, 'During the job the live instrument is the net pressure slope on log scales, but afterwards the fracture is logged rather than argued over.'),
  ('stimulation', 'intermediate', 'final', null, 33, 'A manager asks why the team scopes designs on two dimensional models when planar three dimensional simulators exist. What is the defence?', '["Two dimensional models are more accurate on contained fractures.", "The simulators cannot handle leakoff, so a two dimensional balance has to be run alongside them on every job in any case.", "There is no defence, and the tier presents these models only for historical interest.", "The closed form lets you sweep a variable and read the trend, which is how a feel for the trade offs is built."]'::jsonb, 3, 'A planar three dimensional simulator gives a better single answer and a far worse feel for the surface around it.'),
  ('stimulation', 'intermediate', 'final', null, 34, 'Slurry is placed in a thin fluid on one job and a crosslinked fluid on another. What happens to the grains in each?', '["In the thin fluid they settle quickly and bank on the bottom, and in the viscous fluid they settle slowly and can convect instead.", "Both behave alike, since the areal loading is the same.", "In the thin fluid they stay suspended because the flow is turbulent, and in the viscous fluid they drop straight out near the wellbore.", "In the thin fluid they bridge at the tip, and in the viscous fluid they are carried past it."]'::jsonb, 0, 'Convection sinks the dense slurry near the wellbore while lighter fluid rises elsewhere, so neither case leaves grain spread evenly.'),
  ('stimulation', 'intermediate', 'final', null, 35, 'Height growth is confirmed on a treatment that was designed at 30 m. Trace what that does to the material balance.', '["The balance is unaffected, since it takes only rate and volume.", "The stored volume grows with height while the leaking area does not, so efficiency actually improves as the fracture climbs out of zone.", "Leaking area grows with height, so the loss rises and efficiency drops below the published 0.1728566723633056.", "The pump time falls, because the taller fracture fills at the same rate over a shorter path."]'::jsonb, 2, 'Fluid that went into unwanted height also did not go into length, so the created half-length falls short of the designed one at the same time.'),
  ('stimulation', 'intermediate', 'final', null, 36, 'Of the five modules in this tier, only one needed an iteration. Why did that one need it when the others did not?', '["Because the leakoff coefficient is measured rather than assumed.", "The balance fixed nothing, so leakoff, pump time and efficiency each depend on the next and have to be converged.", "Because the quadratic in the square root of time has two roots, and only an iteration can decide which of the two is the physical one.", "Because the Nolte factor is nonlinear in efficiency and cannot be inverted."]'::jsonb, 1, 'The other modules bought their closed forms by fixing something, and each stated the price at the time it was paid.'),
  ('stimulation', 'intermediate', 'final', null, 37, 'A student wants to carry the published closure, widths and efficiency into the capstone as a check on his own answers. Should he?', '["Yes, because the published case is the reference the grader uses.", "Yes for the widths and the efficiency, which depend only on the fluid and are therefore common to any case run in strict SI units.", "No, but the plane strain modulus can be reused, as it is a property of the tier rather than of the well.", "No, since the capstone runs on its own conditions and only the method carries over from the published case."]'::jsonb, 3, 'Working the capstone means repeating the order of operations, starting with the modulus and ending with the balance on the average width.'),
  ('stimulation', 'intermediate', 'final', null, 38, 'Name the price that module three charged for its closed form widths, in the terms the tier uses.', '["Width can no longer be bought by pumping harder, because the quarter power flattens rate, viscosity and length alike.", "The height became an output instead of an input.", "The two models stopped disagreeing, since a single shape factor was adopted for both and the widths converged on one another.", "Net pressure lost its dependence on the plane strain modulus."]'::jsonb, 0, 'Pi over five and pi over four are averages of profiles that neither model ever computes, which is the second half of that same bill.'),
  ('stimulation', 'intermediate', 'final', null, 39, 'What did module one give up when it reduced the formation to a plane strain modulus?', '["It gave up the closure stress, which is now assumed rather than read.", "It gave up the Poisson ratio, which disappears into the modulus and can no longer be recovered or checked once the width has been computed.", "The rock became one elastic number, with a single stiffness standing in for everything the formation does mechanically.", "It gave up the distinction between confined and unconfined response."]'::jsonb, 2, 'The habit worth carrying is naming the fixed thing and then naming its price, module by module.'),
  ('stimulation', 'intermediate', 'final', null, 40, 'The Expert tier reports a published optimum dimensionless conductivity of 1.6. What does that single figure warn a designer about?', '["That a fracture is only useful above 1.6 in a dimensionless sense.", "That longer is not automatically better, since half-length and conductivity trade against one another at a fixed proppant mass.", "That the design should aim for the widest possible fracture, because conductivity always rewards width more than it rewards length.", "That the reservoir permeability has to exceed the proppant permeability by that factor."]'::jsonb, 1, 'The comparison runs through a pseudo-skin and an effective wellbore radius, which is where a design becomes a production forecast.'),
  ('stimulation', 'intermediate', 'final', null, 41, 'Crushing, embedment and gel residue all attack a proppant pack. How does the Expert tier account for them?', '["They are ignored, as the pack is treated as clean.", "They are absorbed into the leakoff coefficient, which is calibrated after the job so that the balance and the observed pack agree.", "They are handled by lowering the assumed proppant mass before the schedule is built.", "As a damage factor carried explicitly on the conductivity rather than pretended away or folded into the width."]'::jsonb, 3, 'The pack width is smaller than the dynamic width computed in this tier, and the conductivity that follows is smaller again.'),
  ('stimulation', 'intermediate', 'final', null, 42, 'Why does a treatment open with clean fluid carrying no proppant at all?', '["Because the pumps need a clean fluid to reach full rate safely.", "Because the first fluid in reaches the tip, and the tip is the part of the fracture that carries no proppant in any completed design.", "Grain pumped into a fracture that has not yet been created will bridge, so the pad opens width and loses itself to the rock.", "Because clean fluid leaks off more slowly than slurry and therefore raises the efficiency of the job."]'::jsonb, 2, 'How much of the treatment that pad should be follows from the efficiency alone, which is why the balance has to come first.');
